    if(hash) return;
    if(x.fills&&x.fills[0]&&x.fills[0].type==='IMAGE'){ hash=x.fills[0].imageHash; return; }
    if(x.children) x.children.forEach(findImg);
  }
  findImg(n);
  return hash;
}
