function makeText(str,x,y,size,weight,color){
  const t=figma.createText();
  t.characters=str;
  t.fontName={family:'Inter',style:weight};
  t.fontSize=size;
  t.x=x; t.y=y;
  t.fills=[{type:'SOLID',color:color}];
  return t;
}
function imgHashOf(compId){
  const n=figma.getNodeById(compId);
  let h=null;
  function scan(x){
    if(h) return;
    if(x.fills&&x.fills[0]&&x.fills[0].type==='IMAGE'){ h=x.fills[0].imageHash; return; }
    if(x.children) x.children.forEach(scan);
  }
  scan(n);
  return h;
}
function addImg(compId,w,h,x,y){
  const rf=figma.createFrame();
  rf.resize(w,h); rf.x=x; rf.y=y;
  rf.fills=[{type:'IMAGE',imageHash:imgHashOf(compId),scaleMode:'FILL'}];
  f.appendChild(rf);
  return rf;
}

