function setTabColor(tb, currentTab){
  const tabIcon={
    Home:'Icon_Home_Icon', Shop:'Icon_Search_Icon', Favorites:'Icon_Favorites_Icon',
    Bag:'Icon_Bag_Icon', Profile:'Icon_Profile_Icon'
  };
  const activeIdx=['Home','Shop','Favorites','Bag','Profile'].indexOf(currentTab);
  tb.children.forEach(ch=>{
    if(ch.type==='TEXT'){
      const nm=ch.characters;
      const isActive=(nm===currentTab);
      ch.fills=[{type:'SOLID',color: isActive? {r:0,g:0,b:0} : {r:0.45,g:0.45,b:0.45}}];
    } else if(ch.type==='INSTANCE' && /^Icon_/.test(ch.name)){
      const isActive = (ch.name===tabIcon[currentTab]);
      ch.findAll(n=>n.type==='VECTOR').forEach(v=>{
        const hasFill = v.fills && v.fills[0] && v.fills[0].type==='SOLID';
        if(hasFill){ v.fills=[{type:'SOLID',color: isActive? {r:0,g:0,b:0}:{r:0.45,g:0.45,b:0.45}}]; }
      });
    }
  });
}

