await figma.setCurrentPageAsync(figma.getNodeById('3:2'));
const tabMap={
 '12:34':'Home',  // 09
 '12:35':'Home',  // 10
 '12:36':'Home',  // 11
 '12:37':'Shop',  // 12
 '12:38':'Shop',  // 13
 '12:39':'Home',  // 14
 '12:40':'Shop',  // 15
 '12:41':'Shop',  // 16
 '12:42':'Shop',  // 17
 '12:43':'Home',  // 18
};
const black={r:0,g:0,b:0};
const gray={r:0.45,g:0.45,b:0.45};
const out=[];
for(const fid in tabMap){
  const f=figma.getNodeById(fid);
  const tb=f.children.find(c=>c.name==='Tab Bar');
  if(!tb){ out.push(f.name+': no tabbar'); continue; }
  const current=tabMap[fid];
  // For each tab label text, decide color
  tb.children.forEach(ch=>{
    if(ch.type==='TEXT'){
      const isCurrent = (ch.characters===current);
      ch.fills=[{type:'SOLID',color: isCurrent? black: gray}];
    }
  });
  // color icons: vector fills. Map icon by position order = labels order
  const labels = tb.children.filter(ch=>ch.type==='TEXT').map(ch=>ch.characters);
  let iconIdx=0;
  tb.children.forEach(ch=>{
    if(ch.type==='INSTANCE' && ch.name.indexOf('_Icon')>=0){
      const isCurrent = (labels[iconIdx]===current);
      iconIdx++;
      // recolor all vectors inside
      ch.findAll(n=>n.type==='VECTOR').forEach(v=>{ try{ v.fills=[{type:'SOLID',color: isCurrent? black: gray}]; }catch(e){} });
    }
  });
  out.push(f.name+' current='+current);
}
return out.join('\n');

